public class MeuRunnable implements Runnable {

//MÉTODO PARA RODAR A THREAD
    public void run() {
        System.out.println("Rodando com Runnable: " + Thread.currentThread().getName());
    }

    public static void main(String[] args) {
        Thread t2 = new Thread(new MeuRunnable());
        t2.start();
    }
}

public class LambdaThread {
    public static void main(String[] args) {
        Thread t3 = new Thread(() -> {
            System.out.println("Lambda Thread: " + Thread.currentThread().getName());
        });
        t3.start();
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class UsandoExecutor {
    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2); // 2 threads

        executor.submit(() -> System.out.println("Tarefa 1"));
        executor.submit(() -> System.out.println("Tarefa 2"));

        executor.shutdown(); // sempre finalize!
    }
}

@Configuration
@EnableAsync
public class ConfigAsync {
    @Bean
    public Executor taskExecutor() {
        return Executors.newCachedThreadPool();
    }
}

@Service
public class EnvioEmailService {

    @Async
    public void enviarEmail(String destinatario) {
        System.out.println("Enviando email para: " + destinatario);
        // Simula demora
        try { Thread.sleep(3000); } catch (InterruptedException e) {}
        System.out.println("Email enviado!");
    }
}

@RestController
public class EmailController {

    @Autowired
    private EnvioEmailService service;

    @PostMapping("/enviar")
    public String enviar(@RequestParam String para) {
        service.enviarEmail(para);
        return "Seu email está sendo enviado em background!";
    }
}
